recipes.code:
{
  "inputs": [
    {
      "id": "mailbuttons-api-key",
      "type": "promptString",
      "description": "A scoped Mailbuttons MCP token (mb_sandbox_...). Sandbox-by-default; external send requires human promotion.",
      "password": true
    }
  ],
  "servers": {
    "server": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@mailbuttons/mcp-server@0.1.0"
      ],
      "env": {
        "MAILBUTTONS_API_KEY": "${input:mailbuttons-api-key}",
        "MAILBUTTONS_API_URL": "https://mailbuttons.com"
      }
    }
  }
}
